[ExtensionOf(classStr(SalesUpdateRemain))]
final class METSalesUpdateRemain_Extension
{
    public  boolean isExtractionProcess;
    private boolean orderCheckUpdateDone;
    private boolean orderCheckUpdateResult;
    private boolean skipBusinessEvents;

}

Method.Source:
/// <summary>
/// Enhanced delivery remainder update method that supports custom inventory quantity for catch weight items.
/// </summary>
/// <param name="_salesLine">The sales line to update.</param>
/// <param name="_remainSalesPhysical">Remaining physical sales quantity (used for non-CW items).</param>
/// <param name="_remainInventPhysical">Remaining physical inventory quantity.
/// For CW items: If provided (non-zero), overrides auto-calculation; if 0, calculated from CW quantity.
/// For non-CW items: Used directly.</param>
/// <param name="_cWRemainInventPhysical">Remaining physical catch weight quantity (used for CW items only).</param>
/// <returns>true if update was successful; otherwise, false.</returns>
public boolean metUpdateDeliverRemainder(
    SalesLine      _salesLine,
    InventQty      _pickedSalesPhysical,
    InventQty      _pickedInventoryQty, 
    PdsCWInventQty _pickedCWInventoryQty) 
{
    boolean     ret;
    InventQty   salesPhysicalRemainder      = 0;
    InventQty   inventPhysicalRemainder     = 0;
    InventQty   cwInventPhysicalRemainder   = 0;

    salesPhysicalRemainder      = _pickedSalesPhysical;
    inventPhysicalRemainder     = _pickedInventoryQty;
    cwInventPhysicalRemainder   = _pickedCWInventoryQty;

    if (PdsGlobal::pdsIsCWItem(_salesLine.ItemId))
    {
        InventQty cwRemainingInventPhysical = 
            inventPhysicalRemainder ? inventPhysicalRemainder 
            : PdsCatchWeight::minInventQty(_salesLine.ItemId, cwInventPhysicalRemainder);

        InventQty cwRemainingSalesPhysical  = 
            PdsFormCtrl_UpdateRemain::convertQtyToUOM(_salesLine.ItemId, 
            _salesLine.SalesUnit, inventPhysicalRemainder);

        _salesLine.PdsCWRemainInventPhysical = cwInventPhysicalRemainder;

        ret = this.updateDeliverRemainder(_salesLine, cwRemainingSalesPhysical, cwRemainingInventPhysical);
    }
    else 
    {
        ret = this.updateDeliverRemainder(_salesLine, salesPhysicalRemainder, inventPhysicalRemainder, cwInventPhysicalRemainder);
    }

    return ret;
}

protected SalesTable updateCorrespondingSalesOrder(SalesLine _salesLine)
{
    SalesLine salesLineExtract;

    //bug 347577 - Pick List - Performance of Sales Order extract functionality
    //During the extraction process, we need to skip the Sales Totals calculation, 
    //as it takes approximately 4 seconds per line to process.

    if (!isExtractionProcess)
    {
        salesLineExtract = _salesLine as SalesLine;
    }
    return next updateCorrespondingSalesOrder(salesLineExtract);
}

/// <summary>
/// parameter to identify if process is running under extraction
/// </summary>
/// <param name = "_enableExtraction"> is extraction process </param>
/// <returns> a boolean value </returns>
public boolean metParmIsExtraction(boolean _enableExtraction = false)
{
    isExtractionProcess = _enableExtraction;

    return isExtractionProcess;
}

public void resetOrderCheckUpdate()
{
    orderCheckUpdateDone   = false;
    orderCheckUpdateResult = false;
}

public boolean updateExtractionDeliverRemainder(
  SalesLine      _salesLine,
  InventQty      _remainSalesPhysical,
  InventQty      _remainInventPhysical,
  PdsCWInventQty _cWRemainInventPhysical = 0)
{
    InventQty      diffRemainSalesPhysical       = _salesLine.RemainSalesPhysical - _remainSalesPhysical;
    InventQty      diffRemainInventPhysical      = _salesLine.RemainInventPhysical - _remainInventPhysical;
    PdsCWInventQty diffPdsCWRemainInventPhysical = _salesLine.orig().PdsCWRemainInventPhysical - _cWRemainInventPhysical;
    METProcMetrics procMetrics = METProcMetricsScope::current();

    // Skipped: validateWrite(), cancelCallCenterRelatedRecords(), RetailMCRChannelTable lookup
    _salesLine.RemainSalesPhysical  = _remainSalesPhysical;
    _salesLine.RemainInventPhysical = _remainInventPhysical;

    if (PdsGlobal::pdsIsCWItem(_salesLine.ItemId))
    {
        _salesLine.PdsCWRemainInventPhysical = _cWRemainInventPhysical;
    }

    // checkUpdate is mandatory - validates IC linked PO and locked order state
    if (!orderCheckUpdateDone)
    {
        SalesTableType salesTableType = SalesTableType::construct(_salesLine.salesTable());
        salesTableType.parmSalesLineCaller(_salesLine);
        orderCheckUpdateResult = salesTableType.checkUpdate();
        orderCheckUpdateDone   = true;
    }

    if (!orderCheckUpdateResult)
    {
        return false;
    }

    // Sync IC linked purchase order deliver remainder (mirrors updateDeliverRemainder behaviour)
    this.updateInterCompanyDeliverRemainder(
      _salesLine,
      diffRemainSalesPhysical,
      diffRemainInventPhysical,
      diffPdsCWRemainInventPhysical);

    if (skipBusinessEvents)
    {
        _salesLine.skipBusinessEvents(true);
    }

    using (METSalesLineContext salesLineContext = new METSalesLineContext())
    {
        salesLineContext.skipSalesTableUpdate = true;
        salesLineContext.skipUpdateLoadLines = true;
        salesLineContext.skipBrokerOrderCalc = true;
        salesLineContext.skipRetailSalesLineCreation = true;
        salesLineContext.skipCheckSalesLineStatus = true;
        salesLineContext.skipMETSalesLineBusinessEvents = true;

        _salesLine.write();
    }

    return true;
}

public boolean updateCatchWeightExtractionDeliverRemainder(
  SalesLine      _salesLine,
  PdsCWInventQty _remainingCWInventQty)
{
    InventQty remainingInventPhysical = PdsCatchWeight::minInventQty(_salesLine.ItemId, _remainingCWInventQty);
    InventQty remainingSalesPhysical  = PdsFormCtrl_UpdateRemain::convertQtyToUOM(
      _salesLine.ItemId, _salesLine.SalesUnit, remainingInventPhysical);
    METProcMetrics procMetrics = METProcMetricsScope::current();

    // Capture diffs BEFORE setting new values — needed for IC sync
    InventQty      diffRemainSalesPhysical       = _salesLine.RemainSalesPhysical - remainingSalesPhysical;
    InventQty      diffRemainInventPhysical      = _salesLine.RemainInventPhysical - remainingInventPhysical;
    PdsCWInventQty diffPdsCWRemainInventPhysical = _salesLine.orig().PdsCWRemainInventPhysical - _remainingCWInventQty;

    _salesLine.RemainSalesPhysical       = remainingSalesPhysical;
    _salesLine.RemainInventPhysical      = remainingInventPhysical;
    _salesLine.PdsCWRemainInventPhysical = _remainingCWInventQty;

    // checkUpdate is mandatory - validates IC linked PO and locked order state
    if (!orderCheckUpdateDone)
    {
        SalesTableType salesTableType = SalesTableType::construct(_salesLine.salesTable());
        salesTableType.parmSalesLineCaller(_salesLine);
        orderCheckUpdateResult = salesTableType.checkUpdate();
        orderCheckUpdateDone   = true;
    }

    if (!orderCheckUpdateResult)
    {
        return false;
    }

    // Sync IC linked purchase order deliver remainder
    this.updateInterCompanyDeliverRemainder(
      _salesLine,
      diffRemainSalesPhysical,
      diffRemainInventPhysical,
      diffPdsCWRemainInventPhysical);

    if (skipBusinessEvents)
    {
        _salesLine.skipBusinessEvents(true);
    }

    using (METSalesLineContext salesLineContext = new METSalesLineContext())
    {
        salesLineContext.skipSalesTableUpdate = true;
        salesLineContext.skipUpdateLoadLines = true;
        salesLineContext.skipBrokerOrderCalc = true;
        salesLineContext.skipRetailSalesLineCreation = true;
        salesLineContext.skipCheckSalesLineStatus = true;
        _salesLine.write();
    }

    return true;
}

public boolean parmSkipBusinessEvents(boolean _skipBusinessEvents = skipBusinessEvents)
{
    skipBusinessEvents = _skipBusinessEvents;
    return skipBusinessEvents;
}
